package io.github.jesterportfolio.hearth.survival.economy;

import io.github.jesterportfolio.hearth.economy.*;
import io.github.jesterportfolio.hearth.inventory.InventorySaveSession;
import java.util.*;
import org.bukkit.*;
import org.bukkit.entity.Player;
import org.bukkit.event.*;
import org.bukkit.event.inventory.*;
import org.bukkit.inventory.*;
import org.bukkit.plugin.java.JavaPlugin;
import net.kyori.adventure.text.Component;

/** 기존 PeerTrade의 제안/revision/양쪽 확인을 사용하는 생존 UI. 커서/GUI 아이템은 거래하지 않습니다. */
public final class NativePeerMenu implements Listener,AutoCloseable {
    private final JavaPlugin plugin;private final SurvivalEconomy economy;private final Map<UUID,Board> boards=new HashMap<>();private boolean closed;
    private final class Board{final Player first,second;final Object firstToken,secondToken;final PeerTrade deal;final Map<UUID,Map<Integer,NativeItemExchange.Quote>> previews=new HashMap<>();final long expires=System.currentTimeMillis()+180000;Board(Player a,Player b){first=a;second=b;firstToken=economy.token(a);secondToken=economy.token(b);deal=new PeerTrade(UUID.randomUUID(),economy.settings.realm(),a.getUniqueId(),b.getUniqueId());}}
    private final class Screen implements InventoryHolder{final Board board;final Player player;final long revision;final int page;final Inventory inventory;final Map<Integer,String> goods=new HashMap<>();Screen(Board b,Player p,int page){board=b;player=p;revision=b.deal.revision();this.page=page;inventory=Bukkit.createInventory(this,54,Component.text("플레이어 거래"));}public Inventory getInventory(){return inventory;}}
    public NativePeerMenu(JavaPlugin plugin,SurvivalEconomy economy){this.plugin=plugin;this.economy=economy;Bukkit.getPluginManager().registerEvents(this,plugin);Objects.requireNonNull(plugin.getCommand("hearthtrade")).setExecutor((sender,cmd,label,args)->{if(sender instanceof Player p)command(p,args);return true;});}
    public boolean busy(UUID id){return boards.containsKey(id);}
    private boolean near(Board b){boolean committing=b.deal.state()==PeerTrade.State.COMMITTING;return !closed&&economy.same(b.first,b.firstToken)&&economy.same(b.second,b.secondToken)&&(committing||economy.free(b.first)&&economy.free(b.second))&&b.first.getWorld()==b.second.getWorld()&&b.first.getLocation().distanceSquared(b.second.getLocation())<=36;}
    private void say(Board b,String text){for(var p:List.of(b.first,b.second))if(p.isOnline()&&Bukkit.getPlayer(p.getUniqueId())==p)p.sendMessage(Component.text(text));}
    private void remove(Board b){boards.remove(b.first.getUniqueId(),b);boards.remove(b.second.getUniqueId(),b);for(var p:List.of(b.first,b.second))if(p.getOpenInventory().getTopInventory().getHolder() instanceof NativePeerMenu.Screen s&&s.board==b)p.closeInventory();}
    private void cancel(Board b,UUID actor){b.deal.cancel(actor);if(b.deal.state()==PeerTrade.State.HOLD){economy.transactions.invalidate(actor);say(b,"거래 결과 보류 · 관리자 확인이 필요합니다. "+b.deal.id());}else{say(b,"거래를 취소했습니다. 제안한 상품·화폐는 이동하지 않았습니다.");remove(b);}}
    public void invalidate(UUID actor){var b=boards.get(actor);if(b!=null){if(b.deal.state()==PeerTrade.State.COMMITTING&&!economy.transactions.busy(actor))remove(b);else cancel(b,actor);}}
    public void tick(){if(closed)return;for(var b:new HashSet<>(boards.values()))if(b.deal.state()!=PeerTrade.State.HOLD&&(!near(b)||System.currentTimeMillis()>=b.expires))cancel(b,b.first.getUniqueId());}
    public void command(Player p,String[] args){try{if(!economy.free(p))throw new IllegalStateException();String action=args.length==0?"help":args[0];
        if(action.equals("request")&&args.length==2){var target=Bukkit.getPlayerExact(args[1]);if(boards.size()>=256||busy(p.getUniqueId())||target==null||target==p||!economy.free(target)||busy(target.getUniqueId())||p.getWorld()!=target.getWorld()||p.getLocation().distanceSquared(target.getLocation())>36)throw new IllegalStateException();var b=new Board(p,target);boards.put(p.getUniqueId(),b);boards.put(target.getUniqueId(),b);p.sendMessage(Component.text("거래를 요청했습니다."));target.sendMessage(Component.text(p.getName()+"의 거래 요청 · /거래 accept 또는 /거래 cancel"));return;}
        if(action.equals("receipt")&&args.length==2){var token=economy.token(p);economy.store.peerReceipt(economy.context(p),UUID.fromString(args[1])).whenCompleteAsync((row,error)->{if(economy.same(p,token))p.sendMessage(Component.text(error!=null?"거래 기록 조회 실패":row.isEmpty()?"확정 기록 없음 · 거래를 재요청하지 마세요.":"확정 거래: "+row.get().id()+" / 내 제안: "+(row.get().first().equals(p.getUniqueId())?row.get().firstOffer():row.get().secondOffer())));},economy.owner);return;}
        if(action.equals("help")){p.sendMessage(Component.text("/거래 request <이름> · accept · show · cancel · item <상품> <수량> · money <금액> · slot <가방칸 1~36> <수량> · receipt <요청 번호>"));return;}
        var b=boards.get(p.getUniqueId());if(b==null||!near(b))throw new IllegalStateException();if(action.equals("cancel")&&args.length==1){cancel(b,p.getUniqueId());return;}if(action.equals("accept")&&args.length==1){b.deal.accept(p.getUniqueId());show(b,b.first,0);show(b,b.second,0);return;}if(action.equals("show")&&args.length==1){show(b,p,0);return;}
        if(action.equals("slot")&&args.length==3){select(b,p,Integer.parseInt(args[1])-1,Integer.parseInt(args[2]));return;}
        var old=b.deal.offer(p.getUniqueId());if(action.equals("money")&&args.length==2){b.deal.edit(p.getUniqueId(),new PeerTrade.Offer(old.goods(),Long.parseLong(args[1]),old.items()));refresh(b);return;}if(action.equals("item")&&args.length==3){if(!economy.content.goods().containsKey(args[1]))throw new IllegalArgumentException();int n=Integer.parseInt(args[2]);if(n<0||n>4096)throw new IllegalArgumentException();var goods=new HashMap<>(old.goods());if(n==0)goods.remove(args[1]);else goods.put(args[1],n);b.deal.edit(p.getUniqueId(),new PeerTrade.Offer(goods,old.money(),old.items()));refresh(b);return;}throw new IllegalArgumentException();
    }catch(RuntimeException refused){p.sendMessage(Component.text("가까운 활성 참가자와 현재 거래 제안을 확인하세요."));}}
    private void icon(Screen s,int slot,Material material,String title,String... lore){var item=new ItemStack(material);item.editMeta(m->{m.displayName(Component.text(title));m.lore(Arrays.stream(lore).map(Component::text).toList());});s.inventory.setItem(slot,item);}
    private void show(Board b,Player p,int page){if(!near(b)||b.deal.state()!=PeerTrade.State.OPEN)return;var all=economy.content.goods().keySet().stream().sorted().toList();int pages=Math.max(1,Math.max((all.size()+15)/16,(Math.max(b.deal.offer(b.first.getUniqueId()).items().size(),b.deal.offer(b.second.getUniqueId()).items().size())+2)/3));page=Math.clamp(page,0,pages-1);var s=new Screen(b,p,page);UUID other=p==b.first?b.second.getUniqueId():b.first.getUniqueId();var own=b.deal.offer(p.getUniqueId());var theirs=b.deal.offer(other);icon(s,0,Material.PAPER,"내 제안 · 화폐 "+own.money(),"좌클릭 +1 / 우클릭 -1 · Shift는 16개","제안 변경 시 양쪽 확인이 취소됩니다.","ESC 후 제안 유지 · 3분 뒤 자동 취소");icon(s,8,Material.PAPER,"상대 제안 · 화폐 "+theirs.money());for(int i=page*16;i<Math.min(all.size(),(page+1)*16);i++){String id=all.get(i);int slot=9+((i%16)/4)*9+(i%4);var material=Material.valueOf(economy.content.goods().get(id).material());String name=economy.properties.getProperty("good."+id+".name",id);icon(s,slot,material,name+" · "+own.goods().getOrDefault(id,0)+"개");icon(s,slot+5,material,name+" · "+theirs.goods().getOrDefault(id,0)+"개");s.goods.put(slot,id);}preview(s,b,p.getUniqueId(),own,page,1);preview(s,b,other,theirs,page,5);icon(s,4,Material.CHEST,"가방을 클릭해 실제 물품 제안","좌클릭 +1 · 우클릭 -1 · Shift 좌클릭 전체","변경하면 양쪽 확인이 해제됩니다.");icon(s,45,Material.BARRIER,"취소");icon(s,46,Material.GOLD_NUGGET,"화폐 -10");icon(s,47,Material.GOLD_NUGGET,"화폐 -1");icon(s,48,Material.PAPER,"상품 페이지 "+(page+1)+" / "+pages);icon(s,49,Material.GOLD_NUGGET,"화폐 +1");icon(s,50,Material.GOLD_NUGGET,"화폐 +10");icon(s,51,Material.LIME_DYE,"최종 확인","내 확인: "+b.deal.approvals().contains(p.getUniqueId()),"상대 확인: "+b.deal.approvals().contains(other));icon(s,52,Material.ARROW,"이전 상품");icon(s,53,Material.ARROW,"다음 상품");p.openInventory(s.inventory);}
    private void select(Board b,Player p,int slot,int quantity){if(slot<0||slot>=36||quantity<0||quantity>4096||!near(b)||b.deal.state()!=PeerTrade.State.OPEN)throw new IllegalArgumentException("PEER_SLOT");var old=b.deal.offer(p.getUniqueId());var values=new TreeMap<>(old.items());var previews=b.previews.computeIfAbsent(p.getUniqueId(),id->new HashMap<>());if(quantity==0){values.remove(slot);previews.remove(slot);}else{var item=p.getInventory().getItem(slot);if(item==null||item.isEmpty()||quantity>item.getAmount())throw new IllegalArgumentException("PEER_QUANTITY");var quote=NativeItemExchange.quote(item);int size=previews.entrySet().stream().filter(e->e.getKey()!=slot).mapToInt(e->e.getValue().size()).sum()+quote.size();if(size>io.github.jesterportfolio.hearth.inventory.InventoryPayload.MAX_BYTES)throw new IllegalArgumentException("PEER_OFFER_SIZE");values.put(slot,new PeerTrade.Stack(quote.hash(),quantity));previews.put(slot,quote);}b.deal.edit(p.getUniqueId(),new PeerTrade.Offer(old.goods(),old.money(),values));refresh(b);}
    private void preview(Screen screen,Board board,UUID player,PeerTrade.Offer offer,int page,int start){var slots=offer.items().keySet().stream().sorted().toList();for(int n=page*3;n<Math.min(slots.size(),page*3+3);n++){int slot=slots.get(n);var item=board.previews.getOrDefault(player,Map.of()).get(slot);if(item!=null){var shown=item.item().asQuantity(offer.items().get(slot).quantity());screen.inventory.setItem(start+n%3,shown);}}}
    private void refresh(Board b){for(var p:List.of(b.first,b.second))if(p.getOpenInventory().getTopInventory().getHolder() instanceof NativePeerMenu.Screen s&&s.board==b)show(b,p,s.page);}
    private boolean current(Screen s){return boards.get(s.player.getUniqueId())==s.board&&near(s.board)&&s.board.deal.state()==PeerTrade.State.OPEN&&s.board.deal.revision()==s.revision&&s.player.getOpenInventory().getTopInventory()==s.inventory;}
    @EventHandler(priority=EventPriority.HIGHEST) public void click(InventoryClickEvent e){if(!(e.getView().getTopInventory().getHolder() instanceof NativePeerMenu.Screen s))return;boolean denied=e.isCancelled();e.setCancelled(true);var click=e.getClick();if(e.getClickedInventory()==s.player.getInventory()){if(!NativeMenuRules.allow(e.getWhoClicked()==s.player&&current(s),denied,true,s.player.getItemOnCursor().isEmpty(),click.name(),true))return;int source=e.getSlot();if(source<0||source>=36)return;var item=s.player.getInventory().getItem(source);if(item==null||item.isEmpty())return;var expected=NativeItemExchange.quote(item);int quantity=Math.clamp(s.board.deal.offer(s.player.getUniqueId()).items().getOrDefault(source,new PeerTrade.Stack(expected.hash(),1)).quantity()+(s.board.deal.offer(s.player.getUniqueId()).items().containsKey(source)?0:-1)+(click.isRightClick()?-1:1),0,item.getAmount());if(click.isShiftClick()&&!click.isRightClick())quantity=item.getAmount();final int amount=quantity;Bukkit.getScheduler().runTask(plugin,()->{if(!current(s))return;var current=s.player.getInventory().getItem(source);if(current==null||current.isEmpty()||!expected.matches(current))return;try{select(s.board,s.player,source,amount);}catch(RuntimeException invalid){s.player.sendMessage(Component.text("가방과 제안을 다시 확인하세요."));}});return;}if(!NativeMenuRules.allow(e.getWhoClicked()==s.player&&current(s),denied,e.getClickedInventory()==s.inventory,s.player.getItemOnCursor().isEmpty(),click.name(),true))return;int slot=e.getSlot();Bukkit.getScheduler().runTask(plugin,()->{if(!current(s))return;var b=s.board;var actor=s.player.getUniqueId();try{if(slot==45){cancel(b,actor);return;}if(slot==52||slot==53){show(b,s.player,s.page+(slot==52?-1:1));return;}if(slot==51){if(b.deal.confirm(actor,s.revision))commit(b);else refresh(b);return;}var offer=b.deal.offer(actor);var goods=new HashMap<>(offer.goods());long money=offer.money();if(s.goods.containsKey(slot)){String id=s.goods.get(slot);int n=Math.clamp(goods.getOrDefault(id,0)+(click.isRightClick()?-1:1)*(click.isShiftClick()?16:1),0,4096);if(n==0)goods.remove(id);else goods.put(id,n);}else if(Set.of(46,47,49,50).contains(slot))money=Math.max(0,Math.addExact(money,switch(slot){case 46->-10;case 47->-1;case 49->1;default->10;}));else return;b.deal.edit(actor,new PeerTrade.Offer(goods,money,offer.items()));refresh(b);}catch(RuntimeException invalid){s.player.sendMessage(Component.text("현재 거래 제안을 다시 확인하세요."));}});}
    private void commit(Board b){if(!near(b))return;var first=economy.context(b.first);var second=economy.context(b.second);var request=new EconomyStore.PeerRequest(b.deal.id(),first,second,b.deal.offer(first.playerId()),b.deal.offer(second.playerId()));var a=economy.port(b.first);var c=economy.port(b.second);b.first.closeInventory();b.second.closeInventory();if(!near(b)){b.deal.refused();remove(b);return;}economy.transactions.begin(b.deal.id(),"PEER",List.of(a,c),economy.ledger.peer(request,EconomyStore.Probe.NONE,Map.of(b.first.getUniqueId(),Map.copyOf(b.previews.getOrDefault(b.first.getUniqueId(),Map.of())),b.second.getUniqueId(),Map.copyOf(b.previews.getOrDefault(b.second.getUniqueId(),Map.of()))))).whenCompleteAsync((result,error)->{if(error==null&&b.deal.state()==PeerTrade.State.COMMITTING){b.deal.complete(true);say(b,"플레이어 거래를 완료했습니다.");remove(b);}else if(NativeMenuRules.peerRefusal(InventorySaveSession.code(error))){b.deal.refused();say(b,"잔액·상품·빈 공간을 확인하지 못해 거래하지 않았습니다.");remove(b);}else{b.deal.complete(false);say(b,"플레이어 거래 보류 · 관리자 확인이 필요합니다. "+b.deal.id());}},economy.owner);}
    @EventHandler(priority=EventPriority.HIGHEST) public void drag(InventoryDragEvent e){if(e.getView().getTopInventory().getHolder() instanceof NativePeerMenu.Screen)e.setCancelled(true);}
    @Override public void close(){closed=true;HandlerList.unregisterAll(this);for(var b:new HashSet<>(boards.values()))if(b.deal.state()==PeerTrade.State.INVITED||b.deal.state()==PeerTrade.State.OPEN)cancel(b,b.first.getUniqueId());boards.clear();}
}
